package main

import "fmt"

type Circle struct{ R float64 }

func (c Circle) String() string { return "circle" }

func describe(x any) string {
	switch v := x.(type) {
	case fmt.Stringer:
		return "stringer: " + v.String()
	case Circle:
		return "circle radius"
	default:
		return "other"
	}
}

func main() {
	fmt.Println(describe(Circle{R: 2}))
}

package main

import (
	"cmp"
	"fmt"
)

func Max[T cmp.Ordered](a, b T) T {
	if a > b {
		return a
	}
	return b
}

func main() {
	fmt.Println(Max(1, "a"))
}

package main

import "fmt"

func total(items []any) int {
	sum := 0
	for _, it := range items {
		sum += it.(int)
	}
	return sum
}

func main() {
	fmt.Println(total([]any{1, 2, 3}))
	fmt.Println(total([]any{1, 2, "3"}))
}
